const app=document.getElementById('app');
let completed=[];try{const saved=JSON.parse(localStorage.getItem('power-learning-completed')||'[]');completed=Array.isArray(saved)?saved.filter(x=>Number.isInteger(x)&&x>=0&&x<lessons.length):[]}catch{}
let selectedLab='clearing';let quizPassed=false;
const labNames={energy:['电力 × 时间 = 电量','基础 · 单位与电费'],clearing:['单节点市场出清','进阶 · 边际价格'],contract:['中长期合同差价','进阶 · 价格风险'],settlement:['日前与实时两结算','进阶 · 偏差成本']};
const fmt=(n)=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2});
function heading(title,sub,eye='POWER MARKET ACADEMY'){return `<div class="page-heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><span class="date-label">学习版 01 / 2026</span></div>`}
function home(){const next=lessons.find(l=>!completed.includes(l.id))||lessons[0];app.innerHTML=heading('让每一次学习，都更进一步','从基础概念到市场实务，沿着清晰的路径理解电力市场。')+`<section class="hero"><div class="hero-content"><div class="eyebrow">YOUR LEARNING JOURNEY</div><h2>读懂市场规则，<br>也算得清每一笔电。</h2><p>学习一个概念，完成一个算例，再回到真实规则。<br>今天，从「${next.title.split('：')[0]}」开始。</p><button class="primary" data-lesson="${next.id}">${completed.length?'继续学习':'开始第一课'} <span style="margin-left:18px">↗</span></button></div><div class="diagram" aria-label="概念学习、算例实践与规则应用组成学习路径"><div class="orbit"><div class="core">ϟ</div><div class="node n1">01 / 概念学习</div><div class="node n2">02 / 算例实践</div><div class="node n3">03 / 规则应用</div></div></div></section><div class="stats"><div class="stat"><div><small>递进课程</small><b>${lessons.length}<span>节 / 4 个阶段</span></b><small>从入门走向实务</small></div><div class="stat-icon">▤</div></div><div class="stat"><div><small>交互算例</small><b>4<span>个实验</span></b><small>改变参数，即时理解结果</small></div><div class="stat-icon">⌘</div></div><div class="stat"><div><small>本机学习进度</small><b>${completed.length}<span>/ ${lessons.length} 节</span></b><div class="progress-track"><div class="progress-fill" style="width:${completed.length/lessons.length*100}%"></div></div></div><div class="stat-icon">↗</div></div></div><section><div class="section-head"><div><h2>你的学习路线</h2><p>四个阶段，让知识连接起来</p></div><a class="text-link" href="#courses">查看全部课程 ↗</a></div><div class="path-grid">${stages.map((s,i)=>`<a href="#courses" class="path-card"><div class="path-top"><span class="stage-num">0${i+1}</span><span class="level">${s.level}</span></div><h3>${s.title}</h3><p>${s.desc}</p><div class="path-bottom"><span>3 节课程 · ${lessons.filter(l=>l.stage===i).reduce((a,l)=>a+l.minutes,0)} 分钟</span><span>→</span></div></a>`).join('')}</div></section><div class="lower-grid"><section class="panel"><div class="section-head"><div><h2>把知识放进算例</h2><p>不是只看答案，而是理解计算过程</p></div><a href="#lab" class="text-link">实验室 ↗</a></div>${['clearing','settlement'].map((id,i)=>`<a href="#lab/${id}" class="case-preview"><span class="square">${i?'≈':'▥'}</span><div><h3>${labNames[id][0]}</h3><p>${i?'一笔电费，拆成日前与实时两部分':'调节需求，观察谁决定出清价格'}</p></div><span class="arrow">↗</span></a>`).join('')}</section><section class="panel"><div class="section-head"><div><h2>从官方规则开始</h2><p>带来源、版本和资料类型的阅读入口</p></div><a href="#rules" class="text-link">规则库 ↗</a></div>${[rules[3],rules[5]].map(r=>`<a href="${r.url}" target="_blank" rel="noopener" class="rule-row" style="display:block"><span class="tag">${r.region}</span><h3>${r.title} ↗</h3><small>${r.version} · ${r.status}</small></a>`).join('')}</section></div>`}
function courses(){app.innerHTML=heading('一步一步，建立完整的知识体系','先理解机制，再通过算例验证，最后回到各省的具体规则。','LEARNING PATH')+`<div class="notice">课程可按需阅读，推荐依序学习。完成课后自测后可标记学完；进度保存在当前浏览器。</div>`+stages.map((s,i)=>`<section class="course-stage"><div class="course-stage-heading"><span class="stage-num">0${i+1}</span><div><h2>${s.title}</h2><p class="subtitle">${s.desc}</p></div></div><div class="lesson-grid">${lessons.filter(l=>l.stage===i).map(l=>`<article class="lesson"><span class="tag">${s.level} · ${l.minutes} 分钟</span><h3>${l.title}</h3><p>${l.desc}</p><div class="lesson-actions"><button class="secondary" data-lesson="${l.id}">阅读课程 ↗</button><span class="done">${completed.includes(l.id)?'✓ 已学完':'待学习'}</span></div></article>`).join('')}</div></section>`).join('')}
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;quizPassed=completed.includes(id);document.getElementById('lessonContent').innerHTML=`<div class="dialog-top"><span class="tag">阶段 0${l.stage+1} · ${l.minutes} 分钟</span><button class="close" aria-label="关闭课程">×</button></div><h2>${l.title}</h2><p>${l.desc}</p>${l.sections.map(([t,p])=>`<h3>${t}</h3><p>${p}</p>`).join('')}<div class="quiz"><strong>课后小测 · ${l.quiz.q}</strong>${l.quiz.options.map((o,i)=>`<button data-answer="${i}">${o}</button>`).join('')}<div id="quizFeedback" aria-live="polite">${quizPassed?'这节课已完成，也可以再次练习。':'选择答案，检验你的理解。'}</div></div><div class="modal-actions"><button class="primary dark" id="markDone" ${quizPassed?'':'disabled'}>${completed.includes(id)?'已学完 ✓':'标记学完'}</button>${l.lab?`<button class="secondary" id="toLab">动手做对应算例 ↗</button>`:''}</div>`;const dialog=document.getElementById('lessonDialog');if(!dialog.open)dialog.showModal();dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.answer)===l.quiz.answer;b.className=correct?'correct':'wrong';document.getElementById('quizFeedback').textContent=(correct?'✓ 回答正确。':'再试一次。')+l.quiz.explain;if(correct){quizPassed=true;document.getElementById('markDone').disabled=false}});document.getElementById('markDone').onclick=()=>{if(!quizPassed)return;if(!completed.includes(id))completed.push(id);let persisted=true;try{localStorage.setItem('power-learning-completed',JSON.stringify(completed))}catch{persisted=false}document.getElementById('markDone').textContent='已学完 ✓';document.getElementById('quizFeedback').textContent=persisted?'✓ 本机学习进度已保存。':'✓ 本次进度已记录；浏览器不允许保存，刷新后可能丢失。';render()};if(l.lab)document.getElementById('toLab').onclick=()=>{dialog.close();location.hash=`lab/${l.lab}`}}
function field(id,label,value,min=0,max=1000000){return `<label>${label}<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="any" required></label>`}
function lab(){app.innerHTML=heading('算例实验室','改变一个参数，看懂价格和电量背后的逻辑。','CALCULATION LAB')+`<div class="lab-layout"><div class="lab-menu">${Object.entries(labNames).map(([id,[t,d]])=>`<button class="lab-choice ${id===selectedLab?'active':''}" data-lab="${id}"><b>${t}</b><small>${d}</small></button>`).join('')}</div><section class="panel lab-main" id="labPanel"></section></div>`;const p=document.getElementById('labPanel');let f='',sub='';if(selectedLab==='clearing'){sub='三台机组按报价排序，在一个 1 小时时段内满足需求。';f=`<label>需求功率：<strong id="demandLabel">150</strong> MW<input id="demand" type="range" min="1" max="350" value="150" step="1"></label><p class="subtitle">机组 A：80 MW / 180 元 · B：100 MW / 300 元 · C：120 MW / 480 元</p>`}if(selectedLab==='energy'){sub='恒定功率下，先计算电量，再按电能量价格计算费用。';f=`<div class="fields">${field('power','功率（MW）',80)}${field('hours','运行时长（小时）',0.25,0,8760)}${field('price','电能量价格（元/MWh）',350,-100000)}</div>`}if(selectedLab==='contract'){sub='发电侧差价合约教学模型：观察合同覆盖与现货敞口。';f=`<div class="fields">${field('actual','实际发电量（MWh）',100)}${field('contract','合同电量（MWh）',80)}${field('cp','合同价格（元/MWh）',350,-100000)}${field('sp','现货价格（元/MWh）',500,-100000)}</div>`}if(selectedLab==='settlement'){sub='用电侧教学模型：日前电量按日前价，实际偏差按实时价。';f=`<div class="fields">${field('da','日前电量（MWh）',100)}${field('actual','实际用电量（MWh）',110)}${field('dap','日前价格（元/MWh）',300,-100000)}${field('rtp','实时价格（元/MWh）',450,-100000)}</div>`}p.innerHTML=`<span class="tag">交互教学 · 简化模型</span><h2 style="margin-top:14px">${labNames[selectedLab][0]}</h2><p class="subtitle">${sub}</p>${f}<div id="calculation" aria-live="polite"></div><div class="notice" style="margin-bottom:0">模型边界：仅计算所示电能量项目，不含网络与机组复杂约束、输配电及其他费用。实际交易和结算需按适用规则执行。</div>`;p.querySelectorAll('input').forEach(e=>e.addEventListener('input',calculate));calculate()}
function calculate(){const out=document.getElementById('calculation');const inputs=[...document.querySelectorAll('#labPanel input')];if(inputs.some(e=>e.value.trim()===''||!e.checkValidity()||!Number.isFinite(Number(e.value)))){out.innerHTML='<div class="notice">请填写范围内的有效数字；电量与运行时长不可为负。</div>';return}const v=id=>Number(document.getElementById(id).value);let result='',steps='',visual='';if(selectedLab==='clearing'){const d=v('demand');document.getElementById('demandLabel').textContent=d;const quantities=[Math.min(d,80),Math.min(Math.max(d-80,0),100),Math.min(Math.max(d-180,0),120)];visual=`<div class="bars">${quantities.map((q,i)=>`<div class="bar ${q?'on':''}" style="height:${[80,100,120][i]/120*140}px"><em>${q} MW</em><span>机组 ${'ABC'[i]} · ${[180,300,480][i]} 元</span></div>`).join('')}</div>`;if(d>300){result=`<small>供给不足，缺额</small><br><b>${d-300}</b> MW`;steps='总可用供给为 300 MW。教学模型未设定稀缺定价与应急机制，因此不输出出清价格。'}else{const price=d<=80?180:d<=180?300:480;result=`<small>统一边际出清价格</small><br><b>${price}</b> 元/MWh`;steps=`① 报价从低到高排序：A → B → C。<br>② 中标出力：A ${quantities[0]} MW、B ${quantities[1]} MW、C ${quantities[2]} MW。<br>③ 边际机组为 ${d<=80?'A':d<=180?'B':'C'}，1 小时电能量费用 = ${d} × ${price} = ${fmt(d*price)} 元。`}}if(selectedLab==='energy'){const q=v('power')*v('hours'),cost=q*v('price');result=`<small>电量 / 电能量费用</small><br><b>${fmt(q)}</b> MWh <span style="margin:0 14px;color:#a3b298">/</span> <b>${fmt(cost)}</b> 元`;steps=`① 电量 = ${v('power')} MW × ${v('hours')} h = ${fmt(q)} MWh。<br>② 换算为 ${fmt(q*1000)} kWh。<br>③ 费用 = ${fmt(q)} × ${v('price')} = ${fmt(cost)} 元。`}if(selectedLab==='contract'){const energy=v('actual')*v('sp'),diff=v('contract')*(v('cp')-v('sp')),total=energy+diff;result=`<small>发电侧简化总收入</small><br><b>${fmt(total)}</b> 元`;steps=`① 现货电能量收入 = ${v('actual')} × ${v('sp')} = ${fmt(energy)} 元。<br>② 合同差价 = ${v('contract')} × (${v('cp')} − ${v('sp')}) = ${fmt(diff)} 元。<br>③ 总收入 = ${fmt(energy)} + (${fmt(diff)}) = ${fmt(total)} 元。<br>④ 未覆盖电量 = ${fmt(v('actual')-v('contract'))} MWh；负值表示合同量超过实际量。`}if(selectedLab==='settlement'){const da=v('da')*v('dap'),q=v('actual')-v('da'),rt=q*v('rtp');result=`<small>用电侧简化结算成本</small><br><b>${fmt(da+rt)}</b> 元`;steps=`① 日前部分 = ${v('da')} × ${v('dap')} = ${fmt(da)} 元。<br>② 偏差电量 = ${v('actual')} − ${v('da')} = ${fmt(q)} MWh。<br>③ 实时部分 = ${fmt(q)} × ${v('rtp')} = ${fmt(rt)} 元。<br>④ 合计 = ${fmt(da)} + (${fmt(rt)}) = ${fmt(da+rt)} 元。`}out.innerHTML=`<div class="result">${result}</div>${visual}<h3 style="font-size:14px">一步一步算清楚</h3><p class="steps">${steps}</p>`}
function rulesView(){app.innerHTML=heading('规则资料库','从国家框架到省级细则，带着版本和出处阅读。','RULES LIBRARY')+`<div class="notice">已收录 ${rules.length} 条官方资料，其中 ${rules.filter(r=>r.files?.length).length} 条可站内阅读或下载，涵盖规则正文、历史版本、解读与修订动态，尚未覆盖所有省份。来源核对日期：2026-10-04；不表示已确认是最新有效版本。本站文件为收录时的版本，后续修订请对照官方来源。</div><div class="filters"><input id="ruleSearch" aria-label="搜索规则" placeholder="搜索文件名称、文号或关键词…"><select id="regionFilter" aria-label="选择地区"><option value="">全部地区</option>${provinces.map(p=>`<option>${p}</option>`).join('')}</select><select id="typeFilter" aria-label="选择资料主题"><option value="">全部主题</option>${[...new Set(rules.map(r=>r.type))].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="section-head"><h2 id="ruleCount"></h2><span class="subtitle" style="font-size:11px">在本站阅读、下载，按地区和主题筛选</span></div><div class="rule-cards" id="ruleResults"></div>`;['ruleSearch','regionFilter','typeFilter'].forEach(id=>document.getElementById(id).addEventListener('input',filterRules));filterRules()}
function filterRules(){const q=document.getElementById('ruleSearch').value.trim().toLowerCase(),region=document.getElementById('regionFilter').value,type=document.getElementById('typeFilter').value;const found=rules.filter(r=>(!region||r.region===region||(r.regions||[]).includes(region))&&(!type||r.type===type)&&(!q||[r.title,r.version,r.desc,r.region,r.source].join(' ').toLowerCase().includes(q)));document.getElementById('ruleCount').textContent=`${found.length} 条资料`;document.getElementById('ruleResults').innerHTML=found.length?found.map(r=>`<article class="panel rule-card"><div><span class="tag">${r.region}</span> <span class="tag">${r.type}</span></div><h3>${r.title}</h3><p>${r.desc}</p><div class="rule-meta">版本：${r.version}<br>文件 / 来源日期：${r.date}<br>来源：${r.source}<br>资料类型：${r.status}</div>${libraryLinks(r)}<a class="source-link" href="${r.url}" target="_blank" rel="noopener">官方来源 ↗</a></article>`).join(''):`<div class="panel empty">暂未收录匹配资料。<br><p class="subtitle">可切换到“全国”查看基础规则；省级正文与配套文件将逐步补齐。</p><button class="secondary" id="resetFilters">清除筛选</button></div>`;const reset=document.getElementById('resetFilters');if(reset)reset.onclick=()=>{document.getElementById('ruleSearch').value='';document.getElementById('regionFilter').value='';document.getElementById('typeFilter').value='';filterRules()}}
function render(){const [route,arg]=(location.hash.slice(1)||'home').split('/');const page=['home','courses','lab','rules','planner'].includes(route)?route:'home';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));document.getElementById('breadcrumb').textContent='学习工作台 / '+({home:'学习概览',courses:'递进课程',lab:'算例实验室',rules:'省级规则库',planner:'光储盈利规划'}[page]);if(page==='planner')planner();if(page==='home')home();if(page==='courses')courses();if(page==='rules'){if(arg)documentView(arg);else rulesView();}if(page==='lab'){if(arg&&labNames[arg])selectedLab=arg;lab()}document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)));document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{selectedLab=b.dataset.lab;location.hash=`lab/${selectedLab}`})}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_calculation_lesson',description:'Open a power-market teaching calculator; navigates the visible page without completing a lesson.',inputSchema:{type:'object',properties:{caseId:{type:'string',enum:Object.keys(labNames)}},required:['caseId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Object.hasOwn(labNames,input.caseId))throw new Error('Unknown caseId');selectedLab=input.caseId;location.hash=`lab/${selectedLab}`;render();return {caseId:selectedLab,title:labNames[selectedLab][0]}}})).catch(()=>{})}catch{}}
